(\lambda y:B.t)[x:=s]=
\begin{cases}
\lambda y:B[x:=s].t,&y=x,\\
\lambda y:B[x:=s].t[x:=s],&y\ne x,\ y\notin\operatorname{FV}^{x}_{\mathsf F}(s),\\
\lambda z:B[x:=s].(t[y:=z])[x:=s],&y\ne x,\ y\in\operatorname{FV}^{x}_{\mathsf F}(s),
\end{cases}

\{y:B\mid\varphi\}[x:=s]=
\begin{cases}
\{y:B[x:=s]\mid\varphi\},&y=x,\\
\{y:B[x:=s]\mid\varphi[x:=s]\},&y\ne x,\ y\notin\operatorname{FV}^{x}_{\mathsf F}(s),\\
\{z:B[x:=s]\mid(\varphi[y:=z])[x:=s]\},&y\ne x,\ y\in\operatorname{FV}^{x}_{\mathsf F}(s),
\end{cases}

(\forall Y.B)[X:=A]=
\begin{cases}
\forall Y.B,&Y=X,\\
\forall Y.B[X:=A],&Y\ne X,\ Y\notin\operatorname{FV}_X(A),\\
\forall Z.(B[Y:=Z])[X:=A],&Y\ne X,\ Y\in\operatorname{FV}_X(A),
\end{cases}

(\Lambda Y.t)[X:=A]=
\begin{cases}
\Lambda Y.t,&Y=X,\\
\Lambda Y.t[X:=A],&Y\ne X,\ Y\notin\operatorname{FV}^{X}_{\mathsf F}(A),\\
\Lambda Z.(t[Y:=Z])[X:=A],&Y\ne X,\ Y\in\operatorname{FV}^{X}_{\mathsf F}(A),
\end{cases}

\to^0_{\mathsf F}
=
\{((\lambda x:A.t)\,v,t[x:=v]):t,v\in\mathsf{Tm}_{\mathsf F}\}
\cup
\{((\Lambda X.t)[A],t[X:=A]):t\in\mathsf{Tm}_{\mathsf F},A\in\mathsf{Ty}_{\mathsf F}\}
\cup
\{(\operatorname{cast}(t,A),t):\mathsf{TCCProv}_{\mathsf F}(\Gamma,t,A)\}
\cup
\{(\operatorname{assert}(\varphi);t,t):\Gamma\vdash\varphi\ \mathsf{true}\}.

\mathsf{AxJdg}_{\mathsf F}
=
\{\Gamma\vdash x:A\ !\ \mathsf{Tot}:x:A\in\Gamma\}
\cup
\{\Gamma\vdash\varphi\ \mathsf{true}:\varphi\in\Gamma\}
\cup
\{\Gamma\vdash t=_A t\ \mathsf{true}:t\in\mathsf{Tm}_{\mathsf F},\ A\in\mathsf{Ty}_{\mathsf F}\}.

\mathsf{Delta}_{\mathsf F}
=
(\mathsf{Eff},\to_\epsilon,\{x:A\mid\varphi\},\mathsf{KindRule}_{\mathsf F},\mathsf{TypeRule}_{\mathsf F},\mathsf{TermRule}_{\mathsf F},\mathsf{SubRule}_{\mathsf F},\mathsf{TCCProv}_{\mathsf F},\to^0_{\mathsf F},\to_{\mathsf F},\mathsf{Prop}_{\mathsf F},\operatorname{TCC}_{\mathsf F},\mathsf{Rule}_{\mathsf F},\mathsf{Der}_{\mathsf F}).
